        _this.getLostPoint = function(qrcode) {
            var moduleCount = qrcode.getModuleCount();
            var lostPoint = 0;
            // LEVEL1
            for(var row = 0; row < moduleCount; row += 1)for(var col = 0; col < moduleCount; col += 1){
                var sameCount = 0;
                var dark = qrcode.isDark(row, col);
                for(var r = -1; r <= 1; r += 1){
                    if (row + r < 0 || moduleCount <= row + r) continue;
                    for(var c = -1; c <= 1; c += 1){
                        if (col + c < 0 || moduleCount <= col + c) continue;
                        if (r == 0 && c == 0) continue;
                        if (dark == qrcode.isDark(row + r, col + c)) sameCount += 1;
                    }
                }
                if (sameCount > 5) lostPoint += 3 + sameCount - 5;
            }
            // LEVEL2
            for(var row = 0; row < moduleCount - 1; row += 1)for(var col = 0; col < moduleCount - 1; col += 1){
                var count = 0;
                if (qrcode.isDark(row, col)) count += 1;
                if (qrcode.isDark(row + 1, col)) count += 1;
                if (qrcode.isDark(row, col + 1)) count += 1;
                if (qrcode.isDark(row + 1, col + 1)) count += 1;
                if (count == 0 || count == 4) lostPoint += 3;
            }
            // LEVEL3
            for(var row = 0; row < moduleCount; row += 1){
                for(var col = 0; col < moduleCount - 6; col += 1)if (qrcode.isDark(row, col) && !qrcode.isDark(row, col + 1) && qrcode.isDark(row, col + 2) && qrcode.isDark(row, col + 3) && qrcode.isDark(row, col + 4) && !qrcode.isDark(row, col + 5) && qrcode.isDark(row, col + 6)) lostPoint += 40;
            }
            for(var col = 0; col < moduleCount; col += 1){
                for(var row = 0; row < moduleCount - 6; row += 1)if (qrcode.isDark(row, col) && !qrcode.isDark(row + 1, col) && qrcode.isDark(row + 2, col) && qrcode.isDark(row + 3, col) && qrcode.isDark(row + 4, col) && !qrcode.isDark(row + 5, col) && qrcode.isDark(row + 6, col)) lostPoint += 40;
            }
            // LEVEL4
            var darkCount = 0;
            for(var col = 0; col < moduleCount; col += 1){
                for(var row = 0; row < moduleCount; row += 1)if (qrcode.isDark(row, col)) darkCount += 1;
            }
            var ratio = Math.abs(100 * darkCount / moduleCount / moduleCount - 50) / 5;
            lostPoint += ratio * 10;
            return lostPoint;
        };
