function fileSize(bytes) {
    const sizes = [
        "bytes",
        "KB",
        "MB",
        "GB",
        "TB"
    ];
    if (bytes === 0) return "0 bytes";
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    const size = i === 0 ? bytes : (bytes / Math.pow(1024, i)).toFixed(2);
    return `${size} ${sizes[i]}`;
}

